DISCLAIMER_TEXT = (
    "\n\n---\n"
    "*Disclaimer: Predictions and insights generated by this AI Investment Agent are derived from machine learning models "
    "across 5 key sectors (Healthcare, Renewable Energy, Technology, Pharmaceuticals, General Market). This application operates purely as "
    "an advisory/research tool and does not execute live financial transactions or constitute certified investment advice.*"
)

def append_disclaimer(content: str) -> str:
    if DISCLAIMER_TEXT not in content:
        return f"{content}{DISCLAIMER_TEXT}"
    return content